//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME: 		HE_FrekvOmf_ATV650_Wrapper
//	CREATOR:	 	William Veim                                                                                                                                                                                                                                                 
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION			DATE				SIGN						DESCRIPTION                                                                                                                                                                                                                                 
// 1.0.0				28.03.2025		William Veim				Initial release
//	1.0.1				15.04.2025		Ruben Byman				Added Cfg_LOTO_InUse
// 1.0.2				05.08.2024		Fredrik Bjerkenes 		Removed NOT from Inp_STO and Inp_Online due to start block being triggered, when not supposed to. 
//	1.0.3				20.01.2026		Ruben Byman				Endret multiplisering for Inp_Energy til logic blokk
//	1.0.4				25.06.2026		Ruben Byman				Bugfix calculation of total on time and total run time
//	1.0.5				30.06.2026		Ruben Byman				Bugfix calculation of energy
//===============================================================================================================================
//
//		DESCRIPTION:
//
//		FUNCTION:
//
//
//===============================================================================================================================

(*************************************************************************
 *	Update Inputs
 *************************************************************************)
 
 // Config Parameter
 Ext_VFD.EXT_Engineering.Auto_Visible:= 							Cfg_Auto_InUse;
Ext_VFD.EXT_General.LocationIndex[0]:=							Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA
Ext_VFD.EXT_Engineering.LCfg_MotorData_Visible:=			FALSE; //ToDo/Checkout
Ext_VFD.EXT_Engineering.ReverseRunning_Visible:=			FALSE; //ToDo/Checkout
Ext_VFD.EXT_Engineering.LCfg_Autotune_Visible:=			TRUE;
Ext_VFD.EXT_Engineering.LCfg_RampTime_Visible:=			TRUE; 
 
// Input Parmeter
FB_VFD_Logic.Cfg_ControllerTAG:=				Cfg_ControllerName;
FB_VFD_Logic.Cfg_ProcessTAG:=					Cfg_ProcessTAG;
FB_VFD_Logic.Inp_AutoRunFwd:=				Inp_AutoStartRef;
FB_VFD_Logic.Inp_AutoSpeedRef:=				Inp_AutoSpeedRef;
FB_VFD_Logic.Inp_Interlock := 					Inp_Interlock;
FB_VFD_Logic.Cfg_Interlock_InUse:=			Cfg_Interlock_InUse;
FB_VFD_Logic.Cfg_STO_InUse:=					Cfg_STO_InUse;
FB_VFD_Logic.Inp_AlmSuppress:=				Inp_AlmSuppress;
FB_VFD_Logic.Inp_AlmSuppressDesc:= 		Inp_AlmSuppressDesc;
FB_VFD_Logic.Cfg_LOTO_InUse :=				Cfg_LOTO_InUse;
FB_VFD_Logic.Inp_ComFault :=					HE_CommFault(PORT:=Cfg_EIP_Interface, IP:=Cfg_DriveIP);

// Fieldbus Input
// Wrk_SwitchedOnDisabled er aktiv i første syklus etter driven spenningssettes. Må derfor ha en timer for å hindre blokkering av start etter spenningsbrudd
Wrk_SwitchedOnDisabled_TON(In:=Ext_VFD_Input.ETA.Bit[6], PT:=T#200ms);
Wrk_LOTO_TON(In:=Inp_LOTO_IO OR NOT Ext_VFD_Input.IL1R.Bit[0], PT:=T#200ms);


FB_VFD_Logic.Inp_STO :=	 						FIND(In1:=HE_ATV_Drive_State(Inp_HMIS := Ext_VFD_Input.HMIS.Wrd,  Cfg_Delimiter := ' - ', Cfg_Composition := 7), In2:='30 - STO') > 0; //Legg ut på alarm der det er nødstopp (FrekvOmf.Intern.Status_Nodstopp);
FB_VFD_Logic.Inp_Online :=						Ext_VFD_Input.ETA.Bit[0];
FB_VFD_Logic.Inp_Ready := 						Ext_VFD_Input.ETA.Bit[1] AND NOT Wrk_SwitchedOnDisabled_TON.Q;
FB_VFD_Logic.Inp_VoltageEnabled :=			Ext_VFD_Input.ETA.Bit[4];
FB_VFD_Logic.Inp_RunningFwd := 				Ext_VFD_Input.ETA.Bit[2];
FB_VFD_Logic.Inp_RunningRev :=				FALSE;
FB_VFD_Logic.Inp_Error  := 							Ext_VFD_Input.ETA.Bit[3];
FB_VFD_Logic.Inp_Warning := 					Ext_VFD_Input.ETA.Bit[7];
FB_VFD_Logic.Inp_Remote :=						Ext_VFD_Input.ETA.Bit[9];
FB_VFD_Logic.Inp_LocalStop := 					Ext_VFD_Input.ETA.Bit[14];
FB_VFD_Logic.Inp_LOTO := 							Wrk_LOTO_TON.Q;

FB_VFD_Logic.Inp_ActSpeed := ScaleTrans(SclIn:=INT_TO_REAL(WORD_TO_INT(Ext_VFD_Input.RFR.Wrd)),
																	  	X0:=REAL#0.0,
																	  	Y0:=REAL#0.0,
																	  	X1:=REAL#500.0,
																	  	Y1:=REAL#100.0);

(*************************************************************************
 *	VFD Power, Current, Energy
 *************************************************************************)
 
 //Power and current scaling is different from VFD size
 IF Ext_VFD_Input.NCV.Wrd <= 19 THEN
	FB_VFD_Logic.Inp_Power := 	WORD_TO_REAL(Ext_VFD_Input.OPRW.Wrd) / 100 ;
	FB_VFD_Logic.Inp_Current := 	WORD_TO_REAL(Ext_VFD_Input.LCR.Wrd) / 100;
ELSIF Ext_VFD_Input.NCV.Wrd > 19 AND Ext_VFD_Input.NCV.Wrd <= 30 THEN
	FB_VFD_Logic.Inp_Power := 	WORD_TO_REAL(Ext_VFD_Input.OPRW.Wrd) / 10 ;
	FB_VFD_Logic.Inp_Current := 	WORD_TO_REAL(Ext_VFD_Input.LCR.Wrd ) / 10;
ELSE
	FB_VFD_Logic.Inp_Power := 	WORD_TO_REAL(Ext_VFD_Input.OPRW.Wrd) ; 
	FB_VFD_Logic.Inp_Current := 	WORD_TO_REAL(Ext_VFD_Input.LCR.Wrd );
END_IF;	

Wrk_Energy := WORD_TO_REAL(Ext_VFD_Input.OE0.Wrd);
Wrk_Energy := Wrk_Energy + (WORD_TO_REAL(Ext_VFD_Input.OE1.Wrd) * 1e3);
Wrk_Energy := Wrk_Energy + (WORD_TO_REAL(Ext_VFD_Input.OE2.Wrd) * 1e6);
Wrk_Energy := Wrk_Energy + (WORD_TO_REAL(Ext_VFD_Input.OE3.Wrd) * 1e9);
FB_VFD_Logic.Inp_Energy := Wrk_Energy/1000;		//kWh

(*************************************************************************
 *	Runtime Statistics
 *************************************************************************)

FB_VFD_Logic.Inp_VFD_TotalRunTime := 	((WORD_TO_UDINT(Ext_VFD_Input.RTH.Wrd[0]) * 65536) + WORD_TO_UDINT(Ext_VFD_Input.RTH.Wrd[1])) / 3600;
FB_VFD_Logic.Inp_VFD_TotalOnTime := 		((WORD_TO_UDINT(Ext_VFD_Input.PTH.Wrd[0]) * 65536) + WORD_TO_UDINT(Ext_VFD_Input.PTH.Wrd[1])) / 3600;

(*************************************************************************
 *	State and error
 *************************************************************************)
	
FB_VFD_Logic.Inp_Active_Error:= 	HE_ATV_Drive_Fault(Inp_LFT := Ext_VFD_Input.LFT.Wrd, Cfg_Delimiter := ' - ', Cfg_Composition := 7);
FB_VFD_Logic.Inp_Actual_State:=	HE_ATV_Drive_State(Inp_HMIS := Ext_VFD_Input.HMIS.Wrd,  Cfg_Delimiter := ' - ', Cfg_Composition := 7);
FB_VFD_Logic.Inp_Active_Warning:= 'VFD Warning'; //Not decoded, generic text	
	
(*************************************************************************
 *	Execute VFD Logic
 *************************************************************************)
 
FB_VFD_Logic(Ext_VFD:=Ext_VFD, 
							Int_Alarm:=Int_Alarm);

(*************************************************************************
 *	Update Outputs
 *************************************************************************)

// Output Parameters
Sts_Alarm :=					FB_VFD_Logic.Sts_AlarmTriggered;
Sts_AvailableAuto := 	FB_VFD_Logic.Sts_AvailableAuto;
Sts_Interlock := 			FB_VFD_Logic.Sts_Interlock;
Sts_RunningFwd := 		FB_VFD_Logic.Inp_RunningFwd;

Ext_VFD_Output.TUN.Bit[0]	 :=  Ext_VFD.EXT_Engineering.LCfg_AutotuneStart; //Start autotuning
Ext_VFD_Output.ACC.Wrd	 :=  UINT_TO_WORD(Ext_VFD.EXT_Engineering.LCfg_RampUpTime); //Ramptime up
Ext_VFD_Output.DEC.Wrd	 :=  UINT_TO_WORD(Ext_VFD.EXT_Engineering.LCfg_RampDownTime); //Ramptime down
Ext_VFD_Output.CMD.Bit[0] :=  FB_VFD_Logic.Out_Enable AND Ext_VFD_Input.ETA.Bit[5]; // Switch on (Logic output AND not quik stop)
Ext_VFD_Output.CMD.Bit[1] :=  TRUE; //Authorization to supply AC power
Ext_VFD_Output.CMD.Bit[2] :=  TRUE; //No quick stop
Ext_VFD_Output.CMD.Bit[3] :=  FB_VFD_Logic.Out_RunFwd; //Run fwd
Ext_VFD_Output.CMD.Bit[7]	 :=  FB_VFD_Logic.Out_FaultReset; //Fault Reset
Ext_VFD_Output.LFR.Wrd	 :=  INT_TO_WORD(REAL_TO_INT(ScaleTrans(SclIn:=FB_VFD_Logic.Out_SpeedRef,
																														X0:=0,
																														Y0:=0,
																														X1:=100,
																														Y1:=500)));

// Fieldbus Output
IF Ext_VFD_Input.TUS.Wrd = 4 THEN
	Ext_VFD.EXT_Engineering.LCfg_AutotuneStart:=FALSE;
END_IF;
